css:
.stack {
  display: grid;
  gap: 16px;
  padding: 24px;
  font-family: system-ui, sans-serif;
}

.tasks {
  display: grid;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.task {
  padding: 8px 12px;
  border-radius: 6px;
  background-color: #f4f4f5;
}

[data-status="doing"] {
  background-color: #ffedd5;
}

[data-status="done"] {
  background-color: #dcfce7;
  color: #166534;
  text-decoration: line-through;
}

.links {
  display: flex;
  gap: 16px;
  margin: 0;
}

.links a {
  color: #c2410c;
}

.links a[href^="https://"]::after {
  content: " ↗";
}

.links a[href$=".pdf"]::after {
  content: " (PDF)";
  color: #71717a;
}
